1	package mevwatch
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"sort"
10		"syscall"
11	)
12	
13	// BuiltinVersionID identifies the built-in rule version, which reproduces
14	// the original fixed rules. It is always available, its parameters are
15	// queryable, and it cannot be overridden.
16	const BuiltinVersionID = "builtin"
17	
18	// ErrUnknownVersion reports a reference to a rule version that was never
19	// registered in the archive.
20	var ErrUnknownVersion = errors.New("unknown version")
21	
22	// ErrVersionConflict reports a re-registration of an existing version ID
23	// with different parameters.
24	var ErrVersionConflict = errors.New("version already registered with different parameters")
25	
26	// SandwichRule configures the sandwich rule: whether it runs and the
27	// severity of its conclusions.
28	type SandwichRule struct {
29		Enabled  bool `json:"enabled"`
30		Severity int  `json:"severity"`
31	}
32	
33	// DisplacementRule configures the displacement rule. A victim is flagged
34	// only when the previous swap's GasPrice strictly exceeds Multiplier times
35	// the victim's.
36	type DisplacementRule struct {
37		Enabled    bool `json:"enabled"`
38		Severity   int  `json:"severity"`
39		Multiplier int  `json:"multiplier"`
40	}
41	
42	// RuleSet is the complete declaration of both detection rules. Every
43	// version must declare both rules in full.
44	type RuleSet struct {
45		Sandwich     SandwichRule     `json:"sandwich"`
46		Displacement DisplacementRule `json:"displacement"`
47	}
48	
49	// RuleVersion is a named, immutable set of rule parameters.
50	type RuleVersion struct {
51		ID    string  `json:"id"`
52		Rules RuleSet `json:"rules"`
53	}
54	
55	// BuiltinVersion returns the version representing the original fixed
56	// rules: sandwich severity 3, displacement severity 2 with multiplier 2.
57	func BuiltinVersion() RuleVersion {
58		return RuleVersion{
59			ID: BuiltinVersionID,
60			Rules: RuleSet{
61				Sandwich:     SandwichRule{Enabled: true, Severity: 3},
62				Displacement: DisplacementRule{Enabled: true, Severity: 2, Multiplier: 2},
63			},
64		}
65	}
66	
67	// toggleSpec and displacementSpec mirror the registration JSON. Pointers
68	// distinguish a missing field from an explicit zero value, and the decoder
69	// rejects unknown fields (including unknown rule names).
70	type toggleSpec struct {
71		Enabled  *bool `json:"enabled"`
72		Severity *int  `json:"severity"`
73	}
74	
75	type displacementSpec struct {
76		Enabled    *bool `json:"enabled"`
77		Severity   *int  `json:"severity"`
78		Multiplier *int  `json:"multiplier"`
79	}
80	
81	type versionSpec struct {
82		ID    *string `json:"id"`
83		Rules *struct {
84			Sandwich     *toggleSpec       `json:"sandwich"`
85			Displacement *displacementSpec `json:"displacement"`
86		} `json:"rules"`
87	}
88	
89	func parseEnabled(name string, v *bool) (bool, error) {
90		if v == nil {
91			return false, fmt.Errorf("rules.%s.enabled is required (boolean)", name)
92		}
93		return *v, nil
94	}
95	
96	func parseSeverity(name string, v *int) (int, error) {
97		if v == nil {
98			return 0, fmt.Errorf("rules.%s.severity is required (integer 1-5)", name)
99		}
100		if *v < 1 || *v > 5 {
101			return 0, fmt.Errorf("rules.%s.severity must be between 1 and 5, got %d", name, *v)
102		}
103		return *v, nil
104	}
105	
106	// ParseRuleVersion validates a registration document. Missing fields,
107	// wrong types, out-of-range values and unknown rules or fields all fail
108	// with a reason.
109	func ParseRuleVersion(raw []byte) (RuleVersion, error) {
110		var spec versionSpec
111		dec := json.NewDecoder(bytes.NewReader(raw))
112		dec.DisallowUnknownFields()
113		if err := dec.Decode(&spec); err != nil {
114			return RuleVersion{}, fmt.Errorf("invalid version spec: %w", err)
115		}
116		if dec.More() {
117			return RuleVersion{}, errors.New("invalid version spec: unexpected trailing data")
118		}
119		if spec.ID == nil || *spec.ID == "" {
120			return RuleVersion{}, errors.New("id must be a non-empty string")
121		}
122		if spec.Rules == nil {
123			return RuleVersion{}, errors.New("rules must declare sandwich and displacement")
124		}
125		if spec.Rules.Sandwich == nil {
126			return RuleVersion{}, errors.New("rules.sandwich is required")
127		}
128		if spec.Rules.Displacement == nil {
129			return RuleVersion{}, errors.New("rules.displacement is required")
130		}
131		sandwichOn, err := parseEnabled("sandwich", spec.Rules.Sandwich.Enabled)
132		if err != nil {
133			return RuleVersion{}, err
134		}
135		sandwichSev, err := parseSeverity("sandwich", spec.Rules.Sandwich.Severity)
136		if err != nil {
137			return RuleVersion{}, err
138		}
139		dispOn, err := parseEnabled("displacement", spec.Rules.Displacement.Enabled)
140		if err != nil {
141			return RuleVersion{}, err
142		}
143		dispSev, err := parseSeverity("displacement", spec.Rules.Displacement.Severity)
144		if err != nil {
145			return RuleVersion{}, err
146		}
147		mult := spec.Rules.Displacement.Multiplier
148		if mult == nil {
149			return RuleVersion{}, errors.New("rules.displacement.multiplier is required (integer 2-100)")
150		}
151		if *mult < 2 || *mult > 100 {
152			return RuleVersion{}, fmt.Errorf("rules.displacement.multiplier must be between 2 and 100, got %d", *mult)
153		}
154		return RuleVersion{
155			ID: *spec.ID,
156			Rules: RuleSet{
157				Sandwich:     SandwichRule{Enabled: sandwichOn, Severity: sandwichSev},
158				Displacement: DisplacementRule{Enabled: dispOn, Severity: dispSev, Multiplier: *mult},
159			},
160		}, nil
161	}
162	
163	// findVersion resolves id against the built-in version and the archive's
164	// registered versions.
165	func findVersion(data archiveData, id string) (RuleVersion, error) {
166		if id == BuiltinVersionID {
167			return BuiltinVersion(), nil
168		}
169		for _, v := range data.Versions {
170			if v.ID == id {
171				return v, nil
172			}
173		}
174		return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
175	}
176	
177	// enabledVersion resolves the archive's currently enabled version. Archives
178	// written before rule versions existed have no marker and run the built-in
179	// rules.
180	func (d archiveData) enabledVersion() (RuleVersion, error) {
181		if d.EnabledVersion == "" {
182			return BuiltinVersion(), nil
183		}
184		return findVersion(d, d.EnabledVersion)
185	}
186	
187	// RegisterVersion validates raw as a rule version spec and stores it in the
188	// archive at dir. Re-registering the same ID with identical parameters
189	// succeeds without adding a version (created is false); the same ID with
190	// different parameters is rejected. The built-in version ID is reserved.
191	// Any failure leaves the archive untouched.
192	func RegisterVersion(dir string, raw []byte) (v RuleVersion, created bool, err error) {
193		v, err = ParseRuleVersion(raw)
194		if err != nil {
195			return RuleVersion{}, false, err
196		}
197		if v.ID == BuiltinVersionID {
198			return RuleVersion{}, false, fmt.Errorf("version id %q is reserved for the built-in rules", BuiltinVersionID)
199		}
200		if err := os.MkdirAll(dir, 0o755); err != nil {
201			return RuleVersion{}, false, err
202		}
203		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
204		if err != nil {
205			return RuleVersion{}, false, err
206		}
207		defer lock.Close()
208	
209		data, err := readArchive(dir)
210		if err != nil {
211			return RuleVersion{}, false, err
212		}
213		for _, existing := range data.Versions {
214			if existing.ID == v.ID {
215				if existing.Rules == v.Rules {
216					return existing, false, nil
217				}
218				return RuleVersion{}, false, fmt.Errorf("%w: %s", ErrVersionConflict, v.ID)
219			}
220		}
221		data.Versions = append(data.Versions, v)
222		if err := writeArchiveAtomic(dir, data); err != nil {
223			return RuleVersion{}, false, err
224		}
225		return v, true, nil
226	}
227	
228	// EnableVersion makes id the archive's active version for later replays.
229	// Enabling an unknown version fails and leaves the current enabled version
230	// unchanged.
231	func EnableVersion(dir, id string) (RuleVersion, error) {
232		if id == "" {
233			return RuleVersion{}, errors.New("version id must not be empty")
234		}
235		if err := os.MkdirAll(dir, 0o755); err != nil {
236			return RuleVersion{}, err
237		}
238		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
239		if err != nil {
240			return RuleVersion{}, err
241		}
242		defer lock.Close()
243	
244		data, err := readArchive(dir)
245		if err != nil {
246			return RuleVersion{}, err
247		}
248		v, err := findVersion(data, id)
249		if err != nil {
250			return RuleVersion{}, err
251		}
252		if data.EnabledVersion == id {
253			return v, nil
254		}
255		data.EnabledVersion = id
256		if err := writeArchiveAtomic(dir, data); err != nil {
257			return RuleVersion{}, err
258		}
259		return v, nil
260	}
261	
262	// ListVersions returns the built-in version plus every version registered
263	// in the archive, along with the currently enabled version ID.
264	func ListVersions(dir string) (versions []RuleVersion, enabled string, err error) {
265		if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
266			return []RuleVersion{BuiltinVersion()}, BuiltinVersionID, nil
267		}
268		lock, err := lockArchive(dir, syscall.LOCK_SH)
269		if err != nil {
270			return nil, "", err
271		}
272		defer lock.Close()
273	
274		data, err := readArchive(dir)
275		if err != nil {
276			return nil, "", err
277		}
278		versions = append([]RuleVersion{BuiltinVersion()}, data.Versions...)
279		enabled = data.EnabledVersion
280		if enabled == "" {
281			enabled = BuiltinVersionID
282		}
283		return versions, enabled, nil
284	}
285	
286	// GetVersion returns one version's full parameters by ID.
287	func GetVersion(dir, id string) (RuleVersion, error) {
288		if id == BuiltinVersionID {
289			return BuiltinVersion(), nil
290		}
291		if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
292			return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
293		}
294		lock, err := lockArchive(dir, syscall.LOCK_SH)
295		if err != nil {
296			return RuleVersion{}, err
297		}
298		defer lock.Close()
299	
300		data, err := readArchive(dir)
301		if err != nil {
302			return RuleVersion{}, err
303		}
304		return findVersion(data, id)
305	}
306	
307	// FindingChange pairs the archived and compared conclusions for one
308	// transaction whose kind or severity differs between the two versions.
309	type FindingChange struct {
310		TxHash   string        `json:"txHash"`
311		Original ReportFinding `json:"original"`
312		Compared ReportFinding `json:"compared"`
313	}
314	
315	// CompareResult is the outcome of re-judging one archived block under a
316	// different rule version. It carries both versions' parameters, both full
317	// conclusion sets, the raw swap evidence, and the per-transaction diff.
318	type CompareResult struct {
319		ChainID          string          `json:"chainId"`
320		BlockHash        string          `json:"blockHash"`
321		BlockNumber      int64           `json:"blockNumber"`
322		OriginalVersion  RuleVersion     `json:"originalVersion"`
323		ComparedVersion  RuleVersion     `json:"comparedVersion"`
324		OriginalFindings []ReportFinding `json:"originalFindings"`
325		ComparedFindings []ReportFinding `json:"comparedFindings"`
326		Swaps            []Swap          `json:"swaps"`
327		Added            []ReportFinding `json:"added"`
328		Removed          []ReportFinding `json:"removed"`
329		Changed          []FindingChange `json:"changed"`
330	}
331	
332	// Compare re-runs detection for one archived block under the given
333	// registered version and diffs the conclusions against the archived
334	// report. It only reads the archive: the original input file is not
335	// needed, and neither the archived report nor the enabled version is
336	// modified.
337	func Compare(dir, chainID, blockHash, versionID string) (CompareResult, error) {
338		if _, err := os.Stat(dir); err != nil {
339			if errors.Is(err, os.ErrNotExist) {
340				return CompareResult{}, ErrUnknownBlock
341			}
342			return CompareResult{}, err
343		}
344		lock, err := lockArchive(dir, syscall.LOCK_SH)
345		if err != nil {
346			return CompareResult{}, err
347		}
348		defer lock.Close()
349	
350		data, err := readArchive(dir)
351		if err != nil {
352			return CompareResult{}, err
353		}
354		var rec *record
355		for i := range data.Records {
356			if data.Records[i].ChainID == chainID && data.Records[i].BlockHash == blockHash {
357				rec = &data.Records[i]
358				break
359			}
360		}
361		if rec == nil {
362			return CompareResult{}, ErrUnknownBlock
363		}
364		compared, err := findVersion(data, versionID)
365		if err != nil {
366			return CompareResult{}, err
367		}
368	
369		original := rec.Findings
370		if original == nil {
371			original = []ReportFinding{}
372		}
373		rejudged := DetectBlockWithRules(rec.Swaps, compared.Rules)
374		swaps := rec.Swaps
375		if swaps == nil {
376			swaps = []Swap{}
377		}
378	
379		origByTx := make(map[string]ReportFinding, len(original))
380		for _, f := range original {
381			origByTx[f.TxHash] = f
382		}
383		compByTx := make(map[string]ReportFinding, len(rejudged))
384		for _, f := range rejudged {
385			compByTx[f.TxHash] = f
386		}
387		added := []ReportFinding{}
388		removed := []ReportFinding{}
389		changed := []FindingChange{}
390		for _, f := range rejudged {
391			if o, ok := origByTx[f.TxHash]; ok {
392				// A transaction present on both sides with a different kind or
393				// severity is a change, never an add plus a remove.
394				if o.Kind != f.Kind || o.Severity != f.Severity {
395					changed = append(changed, FindingChange{TxHash: f.TxHash, Original: o, Compared: f})
396				}
397			} else {
398				added = append(added, f)
399			}
400		}
401		for _, f := range original {
402			if _, ok := compByTx[f.TxHash]; !ok {
403				removed = append(removed, f)
404			}
405		}
406		byTx := func(fs []ReportFinding) {
407			sort.Slice(fs, func(i, j int) bool { return fs[i].TxHash < fs[j].TxHash })
408		}
409		byTx(added)
410		byTx(removed)
411		sort.Slice(changed, func(i, j int) bool { return changed[i].TxHash < changed[j].TxHash })
412	
413		return CompareResult{
414			ChainID:          rec.ChainID,
415			BlockHash:        rec.BlockHash,
416			BlockNumber:      rec.BlockNumber,
417			OriginalVersion:  rec.ruleVersion(),
418			ComparedVersion:  compared,
419			OriginalFindings: original,
420			ComparedFindings: rejudged,
421			Swaps:            swaps,
422			Added:            added,
423			Removed:          removed,
424			Changed:          changed,
425		}, nil
426	}
