357			t.Fatalf("added = %+v", result.Added)
358		}
359		// Both full conclusion sets are present.
360		if len(result.OriginalFindings) != 2 || len(result.ComparedFindings) != 1 {
361			t.Fatalf("findings sets wrong: %+v / %+v", result.OriginalFindings, result.ComparedFindings)
362		}
363		// Compare must not modify the archived report or the enabled version.
364		after, err := Query(dir, "1", "0xcmp")
365		if err != nil {
366			t.Fatal(err)
367		}
368		if after.Version.ID != BuiltinVersionID || len(after.Findings) != 2 || after.Findings[1].Severity != 2 {
369			t.Fatalf("compare modified the archived report: %+v", after)
370		}
371		_, enabled, _ := ListVersions(dir)
372		if enabled != BuiltinVersionID {
373			t.Fatalf("compare changed enabled version to %q", enabled)
374		}
375	}
376	
377	func TestCompareAddedAndSorted(t *testing.T) {
378		dir := t.TempDir()
379		// Builtin flags nothing (front gas 15 < 2*10? no: 15 > 20 false... 15 < 20, no displacement).
380		// A looser version (multiplier 1 not allowed; use severity-only change via multiplier 2 with
381		// front 25 > 20 for 0xvc, and front 21 > 20 for 0xva) — instead register a version with
382		// multiplier 2 but higher sandwich severity to also produce a change; keep it simple:
383		// builtin: no findings; strict2 (multiplier 2, but front 25/21 flagged): two added, hash-sorted.
384		input := `{"chainId":"1","blockHash":"0xadd","blockNumber":3,"swaps":[` +
385			`{"TxHash":"0xfz","Pool":"p1","Trader":"w","In":1,"Out":1,"GasPrice":25,"Index":0},` +
386			`{"TxHash":"0xvz","Pool":"p1","Trader":"u","In":1,"Out":1,"GasPrice":10,"Index":1},` +
387			`{"TxHash":"0xfa","Pool":"p2","Trader":"w","In":1,"Out":1,"GasPrice":21,"Index":2},` +
388			`{"TxHash":"0xva","Pool":"p2","Trader":"u","In":1,"Out":1,"GasPrice":10,"Index":3}]}`
389		reports := replay(t, dir, input)
390		if len(reports[0].Findings) != 2 {
391			t.Fatalf("setup: builtin should flag both (25>20, 21>20): %+v", reports[0].Findings)
392		}
393		// Compare against a version with multiplier 3: 25 > 30 false, 21 > 30 false -> both removed, sorted.
394		spec := `{"id":"x3","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":3}}}`
395		register(t, dir, spec)
396		result, err := Compare(dir, "1", "0xadd", "x3")
397		if err != nil {
398			t.Fatal(err)
399		}
400		if len(result.Removed) != 2 || result.Removed[0].TxHash != "0xva" || result.Removed[1].TxHash != "0xvz" {
401			t.Fatalf("removed not sorted by tx hash: %+v", result.Removed)
402		}
403		// Reverse direction: comparing a no-finding record against builtin adds them.
404		// Use the same block under x3 archived in a second archive for the added case.
405		dir2 := t.TempDir()
406		register(t, dir2, spec)
407		if _, err := ReplayWithVersion(strings.NewReader(input), dir2, "x3"); err != nil {
408			t.Fatal(err)
409		}
410		result2, err := Compare(dir2, "1", "0xadd", BuiltinVersionID)
411		if err != nil {
412			t.Fatal(err)
413		}
414		if len(result2.Added) != 2 || result2.Added[0].TxHash != "0xva" || result2.Added[1].TxHash != "0xvz" {
415			t.Fatalf("added not sorted by tx hash: %+v", result2.Added)
416		}
417		if result2.OriginalVersion.ID != "x3" {
418			t.Fatalf("original version wrong: %+v", result2.OriginalVersion)
419		}
420	}
421	
422	func TestCompareUnknown(t *testing.T) {
423		dir := t.TempDir()
424		replay(t, dir, sandwichInput)
425		if _, err := Compare(dir, "1", "0xmissing", BuiltinVersionID); !errors.Is(err, ErrUnknownBlock) {
426			t.Fatalf("got %v, want ErrUnknownBlock", err)
427		}
428		if _, err := Compare(dir, "1", "0xa", "ghost"); !errors.Is(err, ErrUnknownVersion) {
429			t.Fatalf("got %v, want ErrUnknownVersion", err)
