458		}
459		if len(r.Findings) != 1 || r.Findings[0].Kind != "sandwich" || r.Findings[0].Severity != 3 ||
460			len(r.Findings[0].Evidence) != 3 {
461			t.Fatalf("legacy findings damaged: %+v", r.Findings)
462		}
463		// Compare against a registered version works on the legacy record.
464		register(t, dir, strictSpec)
465		result, err := Compare(dir, "1", "0xleg", "strict")
466		if err != nil {
467			t.Fatal(err)
468		}
469		if result.OriginalVersion != BuiltinVersion() || len(result.OriginalFindings) != 1 {
470			t.Fatalf("legacy compare wrong: %+v", result)
471		}
472		// Continued import judges new blocks under the enabled (builtin) rules
473		// and leaves the legacy record untouched.
474		reports := replay(t, dir, displacementInput)
475		if len(reports) != 1 || reports[0].Version.ID != BuiltinVersionID || len(reports[0].Findings) != 1 {
476			t.Fatalf("continued import wrong: %+v", reports)
477		}
478		data, err := readArchive(dir)
479		if err != nil {
