// validateVersionSpec enforces the registration document grammar: exactly
// one JSON object (whitespace allowed around it), no trailing content, and
// no duplicate keys in any object. Keys are compared by their decoded,
// case-folded name, so escapes ("sand\u0077ich") and case variants
// ("Enabled" vs "enabled") cannot shadow each other.
func validateVersionSpec(raw []byte) error {
	dec := json.NewDecoder(bytes.NewReader(raw))
	tok, err := dec.Token()
	if err == io.EOF {
		return errors.New("invalid version spec: empty input")
	}
	if err != nil {
		return fmt.Errorf("invalid version spec: %w", err)
	}
	d, ok := tok.(json.Delim)
	if !ok || d != '{' {
		return errors.New("invalid version spec: top-level value must be a JSON object")
	}
	if err := validateSpecObject(dec, ""); err != nil {
		return err
